function dump(n, depth){
  let s = '  '.repeat(depth) + n.type + ' "' + n.name + '" ' + n.id;
  if (n.type === 'TEXT') s += ' chars="' + n.characters + '"';
  if ('children' in n) for (const c of n.children) s += '\n' + dump(c, depth+1);
  return s;
}
