function txt(chars, style, size, color, opts){
  const t = figma.createText();
  t.fontName = {family:'Inter',style};
  t.fontSize = size; t.characters = chars;
  t.fills = [{type:'SOLID',color}];
  opts = opts||{};
  if (opts.ls) t.letterSpacing = {value:opts.ls,unit:'PIXELS'};
  if (opts.lh) t.lineHeight = {value:opts.lh,unit:'PIXELS'};
  if (opts.name) t.name = opts.name;
  if (opts.align) t.textAlignHorizontal = opts.align;
  return t;
}
async function inst(id){ const c = await figma.getNodeByIdAsync(id); return c.createInstance(); }
function frame(name, w, h, x, y){
  const f = figma.createFrame();
  f.name = name; f.resize(w,h); f.x=x; f.y=y;
  f.fills=[{type:'SOLID',color:C.bg}];
  f.clipsContent=true;
  ws.appendChild(f);
  return f;
}
