async function shell(parent, dark){
  const sb = (await figma.getNodeByIdAsync('1:33')).createInstance();
  sb.x=0; sb.y=0; parent.appendChild(sb);
  const hi = (await figma.getNodeByIdAsync('1:44')).createInstance();
  hi.x=0; hi.y=778; parent.appendChild(hi);
  if (dark){
    // recolor glyphs white
    function recolor(n){
      if (n.type==='VECTOR'||n.type==='RECTANGLE'||n.type==='ELLIPSE'||n.type==='TEXT'||n.type==='BOOLEAN_OPERATION'||n.type==='LINE'){
        try{ if(n.fills && n.fills.length && n.fills[0].type==='SOLID') n.fills=solid(C.white); }catch(e){}
        try{ if(n.strokes && n.strokes.length && n.strokes[0].type==='SOLID') n.strokes=solid(C.white); }catch(e){}
      }
      if('children' in n) for(const c of n.children) recolor(c);
    }
    recolor(sb); recolor(hi);
  }
  return {sb,hi};
}
