const solid = (c,o)=>[{type:'SOLID',color:c,opacity:o===undefined?1:o}];

function txt(chars, size, style, color, opts){
  const t = figma.createText();
  t.fontName = {family:'Inter',style:style};
  t.characters = chars;
  t.fontSize = size;
  t.fills = solid(color);
  if (opts && opts.name) t.name = opts.name;
  if (opts && opts.lh) t.lineHeight = {value:opts.lh,unit:'PIXELS'};
  if (opts && opts.ls) t.letterSpacing = {value:opts.ls,unit:'PIXELS'};
  if (opts && opts.w) { t.textAutoResize='HEIGHT'; t.resize(opts.w, t.height); }
  if (opts && opts.center) t.textAlignHorizontal='CENTER';
  return t;
}
function frame(name, w, h, fill){
  const f = figma.createFrame();
  f.name = name; f.resize(w,h);
  f.fills = fill===undefined ? [] : solid(fill);
  f.clipsContent = true;
  return f;
}
async function shell(parent, dark){
  const sb = (await figma.getNodeByIdAsync('1:33')).createInstance();
  sb.x=0; sb.y=0; parent.appendChild(sb);
  const hi = (await figma.getNodeByIdAsync('1:44')).createInstance();
  hi.x=0; hi.y=778; parent.appendChild(hi);
  if (dark){
    function recolor(n){
      if ('fills' in n){ try{ if(n.fills && n.fills.length && n.fills[0].type==='SOLID') n.fills=solid(C.white); }catch(e){} }
      if ('strokes' in n){ try{ if(n.strokes && n.strokes.length && n.strokes[0].type==='SOLID') n.strokes=solid(C.white); }catch(e){} }
      if('children' in n) for(const c of n.children) recolor(c);
    }
    recolor(sb); recolor(hi);
  }
}
