async function field(label, placeholder, opts){
  const f = (await figma.getNodeByIdAsync('1:26')).createInstance();
  const lbl = f.findOne(n=>n.type==='TEXT' && n.parent===f);
  lbl.characters = label;
  const input = f.findOne(n=>n.name==='Input');
  const ph = input.findOne(n=>n.type==='TEXT');
  if (opts && opts.value){
    ph.characters = opts.value;
    ph.fills = solid(C.ink);
    ph.fontName = {family:'Inter',style:'Medium'};
  } else {
    ph.characters = placeholder;
    ph.fills = solid(C.faint);
  }
  if (opts && opts.focused){
    input.fills = solid(C.white);
    input.strokes = solid(C.brand);
    input.strokeWeight = 1.5;
    input.effects = [{type:'DROP_SHADOW',color:{r:0,g:0.478,b:1,a:0.15},offset:{x:0,y:0},radius:8,spread:0,visible:true,blendMode:'NORMAL'}];
    // caret
    const caret = figma.createRectangle();
    caret.resize(1.5,18); caret.fills = solid(C.brand);
    caret.name = 'Caret';
    // place after text inside input
    input.appendChild(caret);
    try{ caret.x = ph.x + ph.width + 2; caret.y = (input.height-18)/2; }catch(e){}
  }
  return f;
}

