// Form fields
function field(label, placeholder, value, focused, helpIcon) {
  const g = figma.createFrame();
  g.name = 'Field · ' + label;
  g.layoutMode = 'VERTICAL';
  g.itemSpacing = 8;
  g.primaryAxisSizingMode = 'AUTO';
  g.counterAxisSizingMode = 'FIXED';
  g.resize(343, 10);
  g.fills = [];
  sheet.appendChild(g);

  const lblRow = figma.createFrame();
  lblRow.name = 'Label row';
  lblRow.layoutMode = 'HORIZONTAL';
  lblRow.counterAxisSizingMode = 'AUTO';
  lblRow.primaryAxisSizingMode = 'FIXED';
  lblRow.resize(343, 10);
  lblRow.fills = [];
  g.appendChild(lblRow);
  const lbl = txt(label, 13, 'Semi Bold', focused ? C.brand : C.sub);
  lblRow.appendChild(lbl);
  lblRow.layoutGrow = 1;
  if (helpIcon) {
    const hi = helpIco.createInstance();
    hi.name = 'Help';
    lblRow.appendChild(hi);
    hi.resize(16,16);
  }

  const input = figma.createFrame();
  input.name = 'Input';
  input.layoutMode = 'HORIZONTAL';
  input.counterAxisAlignItems = 'CENTER';
  input.paddingLeft = 16; input.paddingRight = 16;
  input.primaryAxisSizingMode = 'FIXED';
  input.counterAxisSizingMode = 'FIXED';
  input.resize(343, 52);
  input.cornerRadius = 14;
  input.fills = [solid(focused ? {r:0.95,g:0.97,b:1} : C.bg)];
  if (focused) {
    input.strokes = [solid(C.brand)];
    input.strokeWeight = 1.5;
  }
  g.appendChild(input);

  const t = txt(value || placeholder, 15, value ? 'Semi Bold' : 'Regular', value ? C.ink : C.faint);
  input.appendChild(t);
  input.layoutGrow = 1;
  if (focused) {
    const caret = figma.createRectangle();
    caret.name = 'Caret';
    caret.resize(2, 20);
    caret.fills = [solid(C.brand)];
    input.appendChild(caret);
  }
  return g;
}

